import * as types from "../types/types";
import pkg from "../../package.json";
import log from "./logger";

export function getDefaultHeaderComment(version?:string): string {
    return `/**
 * Generated by veryExpress@${version} 
 * https://github.com/Justin26l/VeryExpress
 */
`;
}

export function getStaticHeaderComment(): string {
    return `/**
 * Generated by veryExpress 
 * https://github.com/Justin26l/VeryExpress
 */
`;
}

export function getSimpleHeaderComment(): string {
    return `// Generated by veryExpress@${pkg.version}`;
}

export function getSimpleStaticHeaderComment(): string {
    return "// Generated by veryExpress";
}

export function OAuthProviders(compilerOptions: types.compilerOptions): string[] {
    return Object.keys(compilerOptions.auth.oauthProviders!).filter((key) => {
        return compilerOptions.auth.oauthProviders![key] === true;
    });
}

export function isAuthEnabled(compilerOptions: types.compilerOptions): boolean {
    return compilerOptions.auth.localAuth
        || OAuthProviders(compilerOptions).length > 0
        || compilerOptions.auth.firebase === true;
}

export function isFirebaseAuthEnabled(compilerOptions: types.compilerOptions): boolean {
    return isAuthEnabled(compilerOptions) && compilerOptions.auth.firebase === true;
}

export function isAccountDeletionEnabled(compilerOptions: types.compilerOptions): boolean {
    return isAuthEnabled(compilerOptions) && (compilerOptions.auth.deleteAccount ?? true);
}

export function isShowSoftDeleted(compilerOptions: types.compilerOptions): boolean {
    const enabled = compilerOptions.app?.showSoftDeleted ?? false;

    if (enabled) {
        log.warn(
            `app.showSoftDeleted is ON — soft-deleted rows are visible to every query, are writable ` +
            `again through the ordinary CRUD path, and the account-state guard in ` +
            `Authentication.middleware will keep rejecting tombstones. ` +
            `Unset app.showSoftDeleted to restore the default (hidden).`
        );
    }

    return enabled;
}

export function isRbacEnabled(compilerOptions: types.compilerOptions): boolean {
    const roles = compilerOptions.useRBAC?.roles;
    return Array.isArray(roles) && roles.length > 0;
}

export const defaultCompilerOptions: types.compilerOptions = {
    rootDir: ".",
    srcDir: "./src",
    sysDir: "./src/system",
    jsonSchemaDir: "./jsonSchema",
    openapiDir: "./openapi",
    generator: {
        commitBeforeGenerate: false,
    },
    app: {
        enableSwagger: true,
        useUserSchema: true,
        useStatefulRedisAuth: false,
        allowApiCreateUpdate_id: false,
        showSoftDeleted: false,
    },
    useRBAC: {
        roles: ["user"],
        default: "user",
    },
    auth: {
        localAuth: true,
        useHttpOnlyCookieToken: false,
        deleteAccount: true,
        firebase: false,
        oauthProviders: {
            google: false,
            microsoft: false,
            apple: false,
            github: false,
        },
    },
    _:{
        writtedDir: [],
    },
    dbType: "sql",
};

export default {
    defaultCompilerOptions,
    getDefaultHeaderComment,
    getStaticHeaderComment,
    getSimpleHeaderComment,
    getSimpleStaticHeaderComment,
    OAuthProviders,
    isAuthEnabled,
    isFirebaseAuthEnabled,
    isRbacEnabled,
    isAccountDeletionEnabled,
    isShowSoftDeleted,
};